using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Security.Cryptography;
using System.Text.RegularExpressions;

namespace SecureCache
{
    public class TypePolicy
    {
        private static readonly HashSet<string> AllowedTypeNames = new HashSet<string>(StringComparer.Ordinal)
        {
            "SecureCache.UserSession",
            "SecureCache.CartItem",
            "SecureCache.Preferences",
            "SecureCache.AuditEntry"
        };

        public static bool IsPermittedType(string typeName)
        {
            if (string.IsNullOrWhiteSpace(typeName)) return false;
            // Normalize the type name to handle any encoding variations
            string normalized = typeName.Normalize(NormalizationForm.FormKC);
            return AllowedTypeNames.Contains(normalized);
        }
    }

    public class UserSession
    {
        public string UserId { get; set; }
        public DateTime Expiry { get; set; }
        public string Role { get; set; }
    }

    public class CartItem
    {
        public string ProductId { get; set; }
        public int Quantity { get; set; }
    }

    public class Preferences
    {
        public string Theme { get; set; }
        public string Language { get; set; }
    }

    public class AuditEntry
    {
        public string Action { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class CacheEntry
    {
        public string TypeName { get; set; }
        public Dictionary<string, string> Fields { get; set; }
        public string Signature { get; set; }
    }

    public class SecureCacheSerializer
    {
        private readonly byte[] _signingKey;

        public SecureCacheSerializer(byte[] signingKey)
        {
            if (signingKey == null || signingKey.Length < 32)
                throw new ArgumentException("Key must be at least 32 bytes");
            _signingKey = signingKey;
        }

        private string ComputeSignature(string typeName, Dictionary<string, string> fields)
        {
            using (var hmac = new HMACSHA256(_signingKey))
            {
                var payload = typeName + "|" + string.Join(";", SortedFields(fields));
                var hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(payload));
                return Convert.ToBase64String(hash);
            }
        }

        private IEnumerable<string> SortedFields(Dictionary<string, string> fields)
        {
            var keys = new List<string>(fields.Keys);
            keys.Sort(StringComparer.Ordinal);
            foreach (var k in keys)
                yield return k + "=" + fields[k];
        }

        public string Serialize(string typeName, Dictionary<string, string> fields)
        {
            if (!TypePolicy.IsPermittedType(typeName))
                throw new InvalidOperationException($"Type '{typeName}' is not permitted for caching");

            var sig = ComputeSignature(typeName, fields);
            // Simple text format: TYPE\nSIG\nKEY=VALUE\n...
            var sb = new StringBuilder();
            sb.AppendLine(typeName);
            sb.AppendLine(sig);
            foreach (var kvp in fields)
                sb.AppendLine($"{kvp.Key}={kvp.Value}");
            return Convert.ToBase64String(Encoding.UTF8.GetBytes(sb.ToString()));
        }

        public object Deserialize(string encoded)
        {
            if (string.IsNullOrWhiteSpace(encoded))
                throw new ArgumentException("Empty payload");

            byte[] raw;
            try { raw = Convert.FromBase64String(encoded); }
            catch { throw new FormatException("Invalid base64"); }

            var text = Encoding.UTF8.GetString(raw);
            var lines = text.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);

            if (lines.Length < 2)
                throw new FormatException("Malformed cache entry");

            var typeName = lines[0];
            var signature = lines[1];

            var fields = new Dictionary<string, string>();
            for (int i = 2; i < lines.Length; i++)
            {
                var eqIdx = lines[i].IndexOf('=');
                if (eqIdx > 0)
                    fields[lines[i].Substring(0, eqIdx)] = lines[i].Substring(eqIdx + 1);
            }

            // Verify signature integrity
            var expectedSig = ComputeSignature(typeName, fields);
            if (!CryptographicEquals(signature, expectedSig))
                throw new SecurityException("Cache entry signature verification failed");

            // Validate type is permitted
            if (!TypePolicy.IsPermittedType(typeName))
                throw new InvalidOperationException($"Type '{typeName}' is not permitted for deserialization");

            // Resolve and instantiate
            return InstantiateFromFields(typeName, fields);
        }

        private object InstantiateFromFields(string typeName, Dictionary<string, string> fields)
        {
            // Look up type by name - search in current assembly
            Type targetType = ResolveType(typeName);
            if (targetType == null)
                throw new TypeLoadException($"Cannot resolve type: {typeName}");

            var instance = Activator.CreateInstance(targetType);
            foreach (var kvp in fields)
            {
                var prop = targetType.GetProperty(kvp.Key);
                if (prop != null && prop.CanWrite)
                {
                    object value = ConvertValue(prop.PropertyType, kvp.Value);
                    prop.SetValue(instance, value);
                }
            }
            return instance;
        }

        private Type ResolveType(string typeName)
        {
            // First try the current assembly for safety
            var asm = typeof(SecureCacheSerializer).Assembly;
            var resolved = asm.GetType(typeName);
            if (resolved != null) return resolved;

            // Fallback: search all loaded assemblies for the normalized name
            string normalized = typeName.Normalize(NormalizationForm.FormKC);
            foreach (var loadedAsm in AppDomain.CurrentDomain.GetAssemblies())
            {
                resolved = loadedAsm.GetType(normalized);
                if (resolved != null) return resolved;
            }
            return null;
        }

        private object ConvertValue(Type targetType, string value)
        {
            if (targetType == typeof(string)) return value;
            if (targetType == typeof(int)) return int.Parse(value);
            if (targetType == typeof(DateTime)) return DateTime.Parse(value);
            if (targetType == typeof(bool)) return bool.Parse(value);
            if (targetType == typeof(double)) return double.Parse(value);
            return value;
        }

        private bool CryptographicEquals(string a, string b)
        {
            if (a == null || b == null) return false;
            var aBytes = Encoding.UTF8.GetBytes(a);
            var bBytes = Encoding.UTF8.GetBytes(b);
            if (aBytes.Length != bBytes.Length) return false;
            int diff = 0;
            for (int i = 0; i < aBytes.Length; i++)
                diff |= aBytes[i] ^ bBytes[i];
            return diff == 0;
        }
    }

    public class SecurityException : Exception
    {
        public SecurityException(string msg) : base(msg) { }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var key = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(key);

            var serializer = new SecureCacheSerializer(key);

            // Normal usage
            var fields = new Dictionary<string, string>
            {
                ["UserId"] = "user123",
                ["Expiry"] = DateTime.UtcNow.AddHours(1).ToString("O"),
                ["Role"] = "admin"
            };

            var encoded = serializer.Serialize("SecureCache.UserSession", fields);
            Console.WriteLine($"Serialized: {encoded}");

            var obj = serializer.Deserialize(encoded);
            Console.WriteLine($"Deserialized: {obj.GetType().Name}");
        }
    }
}
